# Non-regression test: the packaged code must reproduce the results of the
# original code of the paper (git tag v1.1) on the first 15 genes of the
# application data. Reference generated by dev/verification/make_reference_15genes.R.

test_that("f_selec_mod_metapsg_gv reproduces the original code (tag v1.1)", {
  skip_on_cran()
  ref <- readRDS(test_path("fixtures", "ref_15genes.rds"))
  for (cfg in ref$configs) {
    res <- f_selec_mod_metapsg_gv(ref$sumstat, ref$n_s, alpha = cfg$alpha,
                                  adaptive = cfg$adaptive, eps = cfg$eps, npts = cfg$npts)
    label <- sprintf("adaptive = %s, alpha = %.1f", cfg$adaptive, cfg$alpha)
    expect_equal(as.numeric(res$selmod$lambda), cfg$selmod$lambda, tolerance = 1e-6, label = label)
    expect_equal(as.numeric(res$selmod$MIC), cfg$selmod$MIC, tolerance = 1e-6, label = label)
    expect_identical(as.numeric(res$selmod$ng_hit), cfg$selmod$ng_hit, label = label)
    expect_identical(as.numeric(res$selmod$nv_hit), cfg$selmod$nv_hit, label = label)
    for (i in seq_along(cfg$beta_select)) {
      expect_equal(unname(unlist(res$results[[i]]$beta_select)),
                   unname(unlist(cfg$beta_select[[i]])), tolerance = 1e-6, label = label)
    }
  }
})
